 void tile(LinearLayout row,App a,int weight,int height,int iconSize,int tint){LinearLayout t=column();t.setGravity(Gravity.TOP|Gravity.CENTER_HORIZONTAL);t.setPadding(0,dp(6),0,0);t.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x33ffffff),null,null));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(height),weight);p.setMargins(dp(4),dp(4),dp(4),dp(4));row.addView(t,p);ImageView icon=new ImageView(this);icon.setImageDrawable(a.icon);t.addView(icon,new LinearLayout.LayoutParams(dp(iconSize),dp(iconSize)));TextView name=text(a.name,12,Color.WHITE);name.setMaxLines(2);name.setMinLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(dp(3),dp(4),dp(3),0);t.addView(name,new LinearLayout.LayoutParams(-1,-2));t.setOnClickListener(v->{v.animate().scaleX(.94f).scaleY(.94f).setDuration(75).withEndAction(()->{v.setScaleX(1);v.setScaleY(1);launch(a);}).start();});t.setOnLongClickListener(v->{String key="fav:"+a.key;boolean old=prefs.getBoolean(key,false);prefs.edit().putBoolean(key,!old).putBoolean("custom",true).apply();Toast.makeText(this,old?"أزيل من المفضلة":"أضيف إلى المفضلة",0).show();render();return true;});}
 void render(){grid.removeAllViews();ArrayList<App> list=new ArrayList<>();String q=search.getText().toString().toLowerCase(Locale.ROOT);for(App a:apps)if(drawer?a.name.toLowerCase(Locale.ROOT).contains(q):prefs.getBoolean("fav:"+a.key,false))list.add(a);if(!drawer&&list.isEmpty()){for(App a:apps)if(a.key.contains("tiktok")||a.key.contains("zhiliao")||a.key.contains("whatsapp")||a.key.contains("telegram")||a.key.contains("instagram"))list.add(a);for(App a:apps)if(list.size()<6&&!list.contains(a)&&!a.key.contains("camera")&&!a.key.contains("chrome")&&!a.key.contains("dialer")&&!a.key.contains("messaging"))list.add(a);}int i=0;while(i<list.size()){LinearLayout row=new LinearLayout(this);grid.addView(row);int count=drawer?3:3;int height=drawer?124:112;for(int j=0;j<count;j++){if(i<list.size()){int weight=1;tile(row,list.get(i++),weight,height,drawer?66:62,j==0?0x665177bd:0x665e479c);}else row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}}}
 void page(boolean value){drawer=value;header.setVisibility(value?View.GONE:View.VISIBLE);dock.setVisibility(value?View.GONE:View.VISIBLE);search.setVisibility(value?View.VISIBLE:View.GONE);toggle.setText(value?"⌄   الشاشة الرئيسية":"⌃   مكتبة التطبيقات");if(!value){search.setText("");((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);root.requestFocus();}render();scroll.post(()->scroll.scrollTo(0,0));}
