 class Aurora extends Drawable{Paint p=new Paint(3);public void draw(Canvas c){Rect b=getBounds();float w=b.width(),h=b.height();if(w<=0||h<=0)return;c.drawColor(0xff080d20);if(prefs.getBoolean("black",false))return;p.setShader(new RadialGradient(w*.88f,h*.12f,w*.95f,new int[]{0xff334f79,0xff18283e,0x00080d20},null,Shader.TileMode.CLAMP));c.drawRect(b,p);p.setShader(new RadialGradient(w*.08f,h*.68f,w*.9f,new int[]{0xff6758cf,0xff292345,0x00080d20},null,Shader.TileMode.CLAMP));c.drawRect(b,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));p.setColor(0x227db9ff);for(int j=0;j<2;j++)c.drawOval(w*.25f-j*dp(15),-h*.22f-j*dp(12),w*1.45f+j*dp(15),h*.48f+j*dp(12),p);p.setStyle(Paint.Style.FILL);}public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.OPAQUE;}}
class OrbitClock extends View {Paint p=new Paint(3);OrbitClock(){super(MainActivity.this);}void hand(Canvas c,float angle,float length,float width,int color){p.setColor(color);p.setStrokeWidth(width);p.setStrokeCap(Paint.Cap.ROUND);double a=Math.toRadians(angle);c.drawLine(0,0,(float)Math.sin(a)*length,-(float)Math.cos(a)*length,p);}protected void onDraw(Canvas c){super.onDraw(c);float r=Math.min(getWidth(),getHeight())*.46f;c.save();c.translate(getWidth()/2f,getHeight()/2f);c.scale(r/100,r/100);p.setStyle(Paint.Style.FILL);p.setShader(new RadialGradient(0,0,100,new int[]{0xff243b61,0xff080d20},null,Shader.TileMode.CLAMP));c.drawCircle(0,0,100,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(7);p.setShader(new SweepGradient(0,0,new int[]{0xfff2f5ff,0xff536384,0xffc5d5ef,0xff444c69,0xfff2f5ff},null));c.drawCircle(0,0,97,p);p.setShader(null);p.setStrokeWidth(2);p.setColor(0xff986bff);c.drawCircle(0,0,91,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<60;i++){double a=i*Math.PI/30;float x=(float)Math.sin(a),y=-(float)Math.cos(a);p.setColor(i%5==0?0xffc4a0ff:0xff7184a0);p.setStrokeWidth(i%5==0?2:1);c.drawLine(x*(i%5==0?85:89),y*(i%5==0?85:89),x*92,y*92,p);}p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextAlign(Paint.Align.CENTER);p.setTextSize(14);p.setColor(Color.WHITE);for(int i=1;i<=12;i++){double a=i*Math.PI/6;c.drawText(""+i,(float)Math.sin(a)*73,-(float)Math.cos(a)*73+5,p);}p.setTextSize(8);p.setColor(0xffb6c9eb);c.drawText("ORBIT X",0,-29,p);Calendar now=Calendar.getInstance();float m=now.get(Calendar.MINUTE),sec=now.get(Calendar.SECOND);hand(c,(now.get(Calendar.HOUR)+m/60)*30,48,5,Color.WHITE);hand(c,(m+sec/60)*6,65,3,0xffdbeaff);hand(c,sec*6,79,1.4f,0xffbd86ff);p.setColor(0xffbd86ff);c.drawCircle(0,0,4,p);c.restore();if(isShown())postInvalidateDelayed(1000);} }
class DockIcon extends View {int k;Paint p=new Paint(3);DockIcon(int n){super(MainActivity.this);k=n;}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/48f,getHeight()/48f);p.setColor(0xffe4efff);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.8f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);if(k==0){Path a=new Path();a.moveTo(13,7);a.lineTo(21,16);a.lineTo(16,22);a.quadTo(20,30,27,33);a.lineTo(33,27);a.lineTo(41,35);a.quadTo(39,44,30,41);a.quadTo(10,34,7,15);a.close();c.drawPath(a,p);}else if(k==1){c.drawRoundRect(6,9,42,34,8,8,p);c.drawLine(14,34,10,41,p);c.drawLine(10,41,23,34,p);for(int i=0;i<3;i++)c.drawCircle(15+i*9,22,1,p);}else if(k==2){c.drawRoundRect(5,13,43,39,6,6,p);c.drawLine(16,13,20,7,p);c.drawLine(20,7,29,7,p);c.drawLine(29,7,33,13,p);c.drawCircle(24,26,8,p);}else{c.drawCircle(24,24,18,p);c.drawOval(15,6,33,42,p);c.drawLine(6,24,42,24,p);}c.restore();}}
